/**
 * Seeds the Cooperative registry from the parsed CDA cooperative listing
 * (see /home/user/scripts/parse_cda_cooperatives.py, which converts the
 * real CDA letter "CDA COOPERATIVE LISTING 2025.docx" into clean JSON).
 *
 * Idempotent: upserts by `slug` (stable per name+county, generated by the
 * parser), so re-running this after a corrected re-parse updates existing
 * rows in place instead of creating duplicates.
 *
 * Usage: npx ts-node src/seedCooperatives.ts [path-to-parsed-json]
 * Defaults to /home/user/scripts/cda_cooperatives_parsed.json if no path
 * is given.
 */
import "reflect-metadata";
import * as fs from "fs";
import { AppDataSource } from "./data-source";
import { Cooperative } from "./entities/Cooperative";

interface ParsedCooperative {
    id: string; // slug, from the parser - NOT the DB uuid
    name: string;
    county: string | null;
    location: string;
    commodities: string[];
    membership: { total: number | null; male: number | null; female: number | null; raw: string | null };
    contact: { name: string | null; role: string | null; phones: string[]; raw: string | null };
}

async function seed() {
    const jsonPath = process.argv[2] || "/home/user/scripts/cda_cooperatives_parsed.json";
    if (!fs.existsSync(jsonPath)) {
        console.error(`Parsed cooperative JSON not found at ${jsonPath}`);
        process.exit(1);
    }
    const records: ParsedCooperative[] = JSON.parse(fs.readFileSync(jsonPath, "utf-8"));

    await AppDataSource.initialize();
    console.log(`Database connected. Seeding ${records.length} cooperatives...`);

    const repo = AppDataSource.getRepository(Cooperative);
    let created = 0;
    let updated = 0;

    for (const rec of records) {
        let coop = await repo.findOne({ where: { slug: rec.id } });
        const isNew = !coop;
        if (!coop) coop = new Cooperative();

        coop.slug = rec.id;
        coop.name = rec.name;
        coop.county = rec.county || undefined as any;
        coop.location = rec.location || undefined as any;
        coop.commodities = rec.commodities;
        coop.membershipTotal = rec.membership.total;
        coop.membershipMale = rec.membership.male;
        coop.membershipFemale = rec.membership.female;
        coop.contactName = rec.contact.name || undefined as any;
        coop.contactRole = rec.contact.role || undefined as any;
        coop.contactPhones = rec.contact.phones;
        coop.rawMembership = rec.membership.raw || undefined as any;
        coop.rawContact = rec.contact.raw || undefined as any;
        coop.isActive = true;

        await repo.save(coop);
        if (isNew) created++; else updated++;
    }

    console.log(`Done. Created ${created}, updated ${updated}, total in DB now: ${await repo.count()}.`);
    await AppDataSource.destroy();
}

seed().catch((e) => {
    console.error("Seeding failed:", e);
    process.exit(1);
});
